await writeThinkingStep.call(this, {
  request_id: requestId,
  conversation_id: conversationId,
  site_id: site?.id,
  step_number: Date.now(),
  tool_name: 'list_files',
  status: 'running',
  message: `Listing files in ${path}`,
  details: { path }
});

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/git/trees/${branch}?recursive=1`,
    headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json' },
    timeout: 15000
  });

  const normalizedPath = path.replace(/^\/+/, '').replace(/\/+$/, '');
  let files = (response.tree || []).filter(f => f.type === 'blob').map(f => f.path);
  if (normalizedPath && normalizedPath !== '.') files = files.filter(f => f.startsWith(normalizedPath + '/'));

  const result = files.slice(0, 50).join('\n') || 'No files found in ' + path;

  // Write thinking step - COMPLETE
  await writeThinkingStep.call(this, {
    request_id: requestId,
    conversation_id: conversationId,
    site_id: site?.id,
    step_number: Date.now(),
    tool_name: 'list_files',
    status: 'complete',
    message: `✓ Found ${files.slice(0, 50).length} files in ${path}`,
    details: { path, fileCount: files.slice(0, 50).length }
  });

  return result;
} catch (e) {
  // Write thinking step - ERROR
  await writeThinkingStep.call(this, {
    request_id: requestId,
    conversation_id: conversationId,
    site_id: site?.id,
    step_number: Date.now(),
    tool_name: 'list_files',
    status: 'error',
    message: `Error listing files: ${e.message}`,
    details: { path, error: e.message }
  });

  return 'Error: ' + e.message;
}

