const rawInput = $fromAI('query', 'Search query', 'string') || '';
let query = rawInput.trim();

if (query.startsWith('{')) {
  try { const p = JSON.parse(query); query = p.query || p.input || ''; } catch {}
}

if (!query) return 'Error: Search query required';
if (query.length < 2) return 'Error: Query too short';

const ctx = $('Merge Files')?.item?.json || {};
const { owner, repo, branch, requestId, conversationId, site } = ctx;
if (!owner) return 'Error: No repository context';

// Write thinking step - RUNNING
await writeThinkingStep.call(this, {
  request_id: requestId,
  conversation_id: conversationId,
  site_id: site?.id,
  step_number: Date.now(),
  tool_name: 'search_files',
  status: 'running',
  message: `Searching for "${query}"`,
  details: { query }
});

try {
  // Get file tree
  const treeResponse = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/git/trees/${branch}?recursive=1`,
    headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json' },
    timeout: 15000
  });

  // Filter to source files only
  const sourceExts = ['.tsx', '.ts', '.jsx', '.js', '.css', '.html', '.json', '.md'];
  const files = (treeResponse.tree || [])
    .filter(f => f.type === 'blob' && sourceExts.some(ext => f.path.endsWith(ext)))
    .filter(f => !f.path.includes('node_modules') && !f.path.includes('.next'))
    .slice(0, 30);

  const matches = [];
  const queryLower = query.toLowerCase();

  // Search in files loaded in context first
  const contextFiles = ctx.fileContents || {};
  for (const [path, content] of Object.entries(contextFiles)) {
    if (content.toLowerCase().includes(queryLower)) {
      const lines = content.split('\n');
      for (let i = 0; i < lines.length; i++) {
        if (lines[i].toLowerCase().includes(queryLower)) {
          matches.push({ path, line: i + 1, text: lines[i].trim().substring(0, 60) });
          if (matches.length >= 10) break;
        }
      }
    }
  }

  // Search in other files if not enough matches
  if (matches.length < 10) {
    for (const file of files) {
      if (contextFiles[file.path]) continue; // Skip already searched
      try {
        const fileResponse = await this.helpers.httpRequest({
          method: 'GET',
          url: `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(file.path)}?ref=${branch}`,
          headers: { 'Authorization': 'Bearer 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', 'Accept': 'application/vnd.github+json' },
          timeout: 5000
        });

        if (fileResponse.content) {
          const content = Buffer.from(fileResponse.content, 'base64').toString('utf8');
          if (content.toLowerCase().includes(queryLower)) {
            const lines = content.split('\n');
            for (let i = 0; i < lines.length; i++) {
              if (lines[i].toLowerCase().includes(queryLower)) {
                matches.push({ path: file.path, line: i + 1, text: lines[i].trim().substring(0, 60) });
                break; // One match per file
              }
            }
          }
        }
        if (matches.length >= 10) break;
      } catch {}
    }
  }

  if (matches.length > 0) {
    // Write thinking step - COMPLETE
    await writeThinkingStep.call(this, {
      request_id: requestId,
      conversation_id: conversationId,
      site_id: site?.id,
      step_number: Date.now(),
      tool_name: 'search_files',
      status: 'complete',
      message: `✓ Found "${query}" in ${matches.length} location(s)`,
      details: { query, matchCount: matches.length }
    });

    return 'Found "' + query + '" in ' + matches.length + ' location(s):\n' + 
      matches.map(m => `${m.path}:${m.line} - ${m.text}`).join('\n');
  }

  // Write thinking step - COMPLETE (no results)
  await writeThinkingStep.call(this, {
    request_id: requestId,
    conversation_id: conversationId,
    site_id: site?.id,
    step_number: Date.now(),
    tool_name: 'search_files',
    status: 'complete',
    message: `No results for "${query}"`,
    details: { query, matchCount: 0 }
  });

  return 'No results for: "' + query + '"';
} catch (e) {
  // Write thinking step - ERROR
  await writeThinkingStep.call(this, {
    request_id: requestId,
    conversation_id: conversationId,
    site_id: site?.id,
    step_number: Date.now(),
    tool_name: 'search_files',
    status: 'error',
    message: `Error searching: ${e.message}`,
    details: { query, error: e.message }
  });

  return 'Error: ' + e.message;
}

